:root {
  --bg: #0a0010;
  --pink: #ff2fd0;
  --cyan: #4df7ff;
  --violet: #8b2bff;
  --hot: #ff8ae2;
  --ink: #fff6fe;
  --muted: rgba(255, 246, 254, 0.58);
  --line: rgba(255, 255, 255, 0.15);
  --dock-h: 76px;
  --pad: clamp(18px, 3vw, 38px);
  --display: "Unbounded", "Arial Black", Impact, sans-serif;
  --body: "Space Grotesk", "Helvetica Neue", Arial, sans-serif;
}

body[data-theme="acid"] {
  --bg: #050a00;
  --pink: #d8ff00;
  --cyan: #00ffc8;
  --violet: #ff2f7a;
  --hot: #f2ff9e;
}

body[data-theme="ice"] {
  --bg: #01060f;
  --pink: #7ae7ff;
  --cyan: #c9b8ff;
  --violet: #2f7bff;
  --hot: #eafcff;
}

body[data-theme="inferno"] {
  --bg: #100200;
  --pink: #ff5a1f;
  --cyan: #ffd166;
  --violet: #ff1f6b;
  --hot: #ffb37a;
}

