  }

  .sub {
    max-width: 20rem;
    font-size: 11px;
  }

  .power-desc {
    display: none;
  }

  .dock {
    gap: 8px;
  }

  .power {
    gap: 9px;
    padding: 0 10px;
  }

  .power-icon {
    width: 30px;
    height: 30px;
  }

