  .manifesto {
    top: calc(64px + env(safe-area-inset-top, 0px));
    left: 18px;
    width: calc(100% - 36px);
    padding: 0;
  }

  .eyebrow {
    margin-bottom: 12px;
    font-size: 8px;
    letter-spacing: 0.24em;
  }

  h1 {
    font-size: clamp(1.9rem, 10.4vw, 3rem);
    line-height: 0.9;
  }

  .sub {
    margin-top: 12px;
    max-width: 17rem;
    font-size: 10px;
    line-height: 1.5;
  }

  .sub br {
    display: none;
  }

  .stats {
    margin-top: 12px;
    padding-top: 10px;
    gap: 24px;
  }

  .stat-num {
    font-size: 16px;
  }

  .stat-label {
    font-size: 6.5px;
  }

  .backtype {
    top: 46%;
    font-size: 34vw;
    -webkit-text-stroke-color: rgba(255, 255, 255, 0.07);
  }

  .topbar {
    padding-top: calc(16px + env(safe-area-inset-top, 0px));
  }

  .hint {
    display: none;
  }

  .dock-wrap {
    bottom: calc(10px + env(safe-area-inset-bottom, 0px));
    width: calc(100vw - 20px);
  }

  .dock {
    grid-template-columns: 1fr 1fr;
    gap: 7px;
    padding: 7px;
    border-radius: 22px;
  }

  .power {
    height: var(--dock-h);
    border-radius: 15px;
    padding: 0 9px;
    gap: 8px;
  }

  .power-name {
    font-size: 9px;
    letter-spacing: 0.03em;
  }

  .power-icon {
    width: 27px;
    height: 27px;
  }

  .power-icon svg {
    width: 14px;
    height: 14px;
  }

  kbd {
    display: none;
  }

  .caption {
    bottom: calc(var(--dock-h) * 2 + 48px + env(safe-area-inset-bottom, 0px));
    width: 90vw;
    gap: 5px;
  }

  .caption-kicker {
    font-size: 7px;
  }

  .caption-text {
    font-size: 1.05rem;
  }

  .caption-text.big {
    font-size: 1.5rem;
  }

  #cursor {
    display: none;
  }

  .scanlines {
    opacity: 0.16;
  }
}

@media (max-height: 620px) and (orientation: landscape) {
  .manifesto {
    top: 50%;
    transform: translateY(-50%);
    width: 34vw;
  }

  .sub,
  .stats,
  .hint {
    display: none;
  }

  h1 {
    font-size: clamp(1.6rem, 4.4vw, 2.6rem);
  }

  .dock {
    grid-template-columns: repeat(4, 1fr);
    padding: 6px;
  }

  .power {
    height: 50px;
  }

  .power-desc {
    display: none;
  }

  .caption {
    bottom: calc(50px + 36px);
  }

  .dock-wrap {
    width: min(880px, calc(100vw - 24px));
  }
}

@media (prefers-reduced-motion: reduce) {
  .grain,
  .sigil,
  .pulse-dot,
  .star {
    animation: none !important;
  }
}

import * as THREE from "three";
import { Reflector } from "three/addons/objects/Reflector.js";

export const THEMES = [
  {
    id: "bubblegum",
    name: "BUBBLEGUM",
    a: 0xff2fd0,
    b: 0x4df7ff,
    c: 0x8b2bff,
    bg: 0x0a0010,
  },
  {
    id: "acid",
    name: "ACID BLOOM",
    a: 0xd8ff00,
    b: 0x00ffc8,
    c: 0xff2f7a,
    bg: 0x050a00,
  },
  {
    id: "ice",
    name: "CRYO DREAM",
    a: 0x7ae7ff,
    b: 0xc9b8ff,
    c: 0x2f7bff,
    bg: 0x01060f,
  },
  {
    id: "inferno",
    name: "SOLAR FLARE",
    a: 0xff5a1f,
    b: 0xffd166,
    c: 0xff1f6b,
    bg: 0x100200,
  },
];

function makeEnvScene(palette) {
  const env = new THREE.Scene();
  env.background = new THREE.Color(0x020005);

  const panel = (color, intensity, width, height, position, rotation) => {
    const material = new THREE.MeshBasicMaterial({
      color: new THREE.Color(color).multiplyScalar(intensity),
      side: THREE.DoubleSide,
    });
    const mesh = new THREE.Mesh(new THREE.PlaneGeometry(width, height), material);
    mesh.position.set(...position);
    mesh.rotation.set(...rotation);
    env.add(mesh);
    return mesh;
  };

  panel(palette.a, 5.2, 16, 16, [-9, 4, 0], [0, Math.PI / 2, 0]);
  panel(palette.b, 4.4, 13, 13, [9, 3.5, 1], [0, -Math.PI / 2, 0]);
  panel(palette.c, 3.2, 12, 12, [0, 3.5, -9], [0, 0, 0]);
  panel(0xffffff, 6.5, 10, 2.2, [0, 10, 0], [Math.PI / 2, 0, 0]);
  panel(0xffffff, 2.6, 26, 1.6, [0, -2.4, 4], [-Math.PI / 2, 0, 0]);
  panel(palette.a, 2.4, 3, 12, [-3.5, 5, 8], [0, 0.5, 0]);
  panel(palette.b, 2.2, 3, 10, [4, 5.5, 8], [0, -0.5, 0]);

  return env;
}

export function createEnvironment(scene, renderer, quality) {
  const paletteA = new THREE.Color(THEMES[0].a);
  const paletteB = new THREE.Color(THEMES[0].b);
  const paletteC = new THREE.Color(THEMES[0].c);
  const paletteBg = new THREE.Color(THEMES[0].bg);

  scene.fog = new THREE.FogExp2(paletteBg.clone(), 0.026);

  const sky = new THREE.Mesh(
    new THREE.SphereGeometry(60, 32, 24),
    new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      uniforms: {
        uA: { value: paletteBg.clone() },
        uB: { value: paletteC.clone() },
        uC: { value: paletteA.clone() },
      },
      vertexShader: /* glsl */ `
        varying vec3 vDir;
        void main() {
          vDir = position;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: /* glsl */ `
        uniform vec3 uA;
        uniform vec3 uB;
        uniform vec3 uC;
        varying vec3 vDir;
        void main() {
          vec3 d = normalize(vDir);
          float h = smoothstep(-0.4, 0.8, d.y);
          vec3 col = mix(uA, uB, h * 0.26);
          float horizon = pow(max(0.0, 1.0 - abs(d.y + 0.06)), 6.0);
          col += uC * horizon * 0.14;
          col += uB * 0.018 * sin(d.x * 7.0 + d.y * 11.0);
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    })
  );
  sky.frustumCulled = false;
  scene.add(sky);

  let envTarget = null;
  const pmrem = new THREE.PMREMGenerator(renderer);

  function rebuildEnvironment(a, b, c) {
    const envScene = makeEnvScene({ a: a.getHex(), b: b.getHex(), c: c.getHex() });
    const target = pmrem.fromScene(envScene, 0.035, 0.1, 100);
    scene.environment = target.texture;
    envTarget?.dispose();
    envTarget = target;
    envScene.traverse((child) => {
      if (child.isMesh) {
        child.geometry.dispose();
        child.material.dispose();
      }
    });
  }

  rebuildEnvironment(paletteA, paletteB, paletteC);

  // Mirror-black altar floor.
  const mirror = new Reflector(new THREE.CircleGeometry(18, 96), {
    clipBias: 0.003,
    textureWidth: quality.mirror,
    textureHeight: quality.mirror,
    color: 0x2b0b3d,
    multisample: 0,
  });
  mirror.rotation.x = -Math.PI / 2;
  mirror.position.y = 0;
  scene.add(mirror);

  const gridMaterial = new THREE.ShaderMaterial({
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    uniforms: {
      uTime: { value: 0 },
      uA: { value: paletteA.clone() },
      uB: { value: paletteB.clone() },
    },
    vertexShader: /* glsl */ `
      varying vec2 vUv;
      void main() {
        vUv = uv;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: /* glsl */ `
      uniform float uTime;
      uniform vec3 uA;
      uniform vec3 uB;
      varying vec2 vUv;
      void main() {
        vec2 p = (vUv - 0.5) * 2.0;
        float r = length(p);
        float fade = smoothstep(1.0, 0.08, r) * smoothstep(0.02, 0.16, r);
        vec2 q = abs(fract(p * 11.0) - 0.5);
        float grid = smoothstep(0.455, 0.5, max(q.x, q.y));
        float pulse = fract(uTime * 0.13);
        float ring = smoothstep(0.012, 0.0, abs(r - pulse * 1.35));
        float ring2 = smoothstep(0.008, 0.0, abs(r - fract(uTime * 0.07 + 0.4) * 1.5));
        vec3 col = mix(uA, uB, smoothstep(0.1, 0.9, r));
        float alpha = (grid * 0.18 + ring * 0.5 + ring2 * 0.3) * fade;
        gl_FragColor = vec4(col, alpha);
      }
    `,
  });
  const grid = new THREE.Mesh(new THREE.CircleGeometry(18, 96), gridMaterial);
  grid.rotation.x = -Math.PI / 2;
  grid.position.y = 0.006;
  scene.add(grid);

  // A dark glass dais ring.
  const dais = new THREE.Mesh(
    new THREE.RingGeometry(2.12, 2.86, 128),
    new THREE.MeshPhysicalMaterial({
      color: 0x0b0014,
      metalness: 0.9,
      roughness: 0.18,
      transparent: true,
      opacity: 0.72,
      envMapIntensity: 1.4,
      side: THREE.DoubleSide,
    })
  );
  dais.rotation.x = -Math.PI / 2;
  dais.position.y = 0.008;
  scene.add(dais);

  const daisRimMaterial = new THREE.MeshBasicMaterial({
    color: paletteA.clone(),
    transparent: true,
    opacity: 0.8,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  });
  const daisRim = new THREE.Mesh(new THREE.TorusGeometry(2.86, 0.008, 6, 180), daisRimMaterial);
  daisRim.rotation.x = Math.PI / 2;
  daisRim.position.y = 0.012;
  scene.add(daisRim);

  const daisInnerMaterial = daisRimMaterial.clone();
  daisInnerMaterial.color = paletteB.clone();
  daisInnerMaterial.opacity = 0.45;
  const daisInner = new THREE.Mesh(new THREE.TorusGeometry(2.12, 0.005, 6, 180), daisInnerMaterial);
  daisInner.rotation.x = Math.PI / 2;
  daisInner.position.y = 0.012;
  scene.add(daisInner);

  // Orbital halos.
  const rings = [];
  const ringDefs = [
    { radius: 1.62, tilt: [1.24, 0.18, 0], color: "a", speed: 0.22, gems: 7 },
    { radius: 2.12, tilt: [-0.98, 0.62, 0.22], color: "b", speed: -0.15, gems: 9 },
    { radius: 2.62, tilt: [1.52, -0.42, 0.1], color: "c", speed: 0.1, gems: 11 },
  ];

  ringDefs.forEach((def, index) => {
    const group = new THREE.Group();
    group.position.y = 1.52;
    group.rotation.set(...def.tilt);

    const material = new THREE.MeshBasicMaterial({
      color: paletteA.clone(),
      transparent: true,
      opacity: 0.5,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    });
    const torus = new THREE.Mesh(new THREE.TorusGeometry(def.radius, 0.006, 6, 220), material);
    group.add(torus);

    const gemMaterial = new THREE.MeshBasicMaterial({
      color: 0xffffff,
      transparent: true,
      opacity: 0.9,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    });
    for (let i = 0; i < def.gems; i += 1) {
      const angle = (i / def.gems) * Math.PI * 2;
      const gem = new THREE.Mesh(new THREE.OctahedronGeometry(0.025, 0), gemMaterial);
      gem.position.set(Math.cos(angle) * def.radius, Math.sin(angle) * def.radius, 0);
      gem.rotation.z = angle;
      group.add(gem);
    }

    group.userData = {
      speed: def.speed,
      material,
      gemMaterial,
      colorKey: def.color,
      index,
      tilt: new THREE.Euler(...def.tilt),
    };
    scene.add(group);
    rings.push(group);
  });

  // Floating chrome relics.
  const shardMaterial = new THREE.MeshPhysicalMaterial({
    color: 0xffe9fb,
    metalness: 1,
    roughness: 0.12,
    envMapIntensity: 2.4,
    clearcoat: 1,
    clearcoatRoughness: 0.1,
    iridescence: 1,
    iridescenceIOR: 1.7,
    iridescenceThicknessRange: [120, 620],
  });
  const shards = [];
  const shardCount = quality.mobile ? 7 : 12;
  for (let i = 0; i < shardCount; i += 1) {
    const angle = (i / shardCount) * Math.PI * 2 + Math.random() * 0.5;
    const radius = 1.1 + Math.random() * 1.7;
    const geometry = new THREE.OctahedronGeometry(0.055 + Math.random() * 0.06, 0);
    const shard = new THREE.Mesh(geometry, shardMaterial);
    shard.scale.set(0.8, 2.2 + Math.random() * 1.6, 0.8);
    shard.position.set(Math.cos(angle) * radius, 0.45 + Math.random() * 2.6, Math.sin(angle) * radius);
    shard.rotation.set(Math.random() * 3, Math.random() * 3, Math.random() * 3);
    shard.userData = {
      baseY: shard.position.y,
      phase: Math.random() * Math.PI * 2,
      speed: 0.15 + Math.random() * 0.3,
      radius,
      angle,
      orbit: 0.03 + Math.random() * 0.08,
    };
    scene.add(shard);
    shards.push(shard);
  }

  // Ambient glitter.
  const dustCount = quality.mobile ? 750 : 1800;
  const dustGeometry = new THREE.BufferGeometry();
  const dustPositions = new Float32Array(dustCount * 3);
  const dustSizes = new Float32Array(dustCount);
  const dustSeeds = new Float32Array(dustCount);
  for (let i = 0; i < dustCount; i += 1) {
    const radius = 2.2 + Math.pow(Math.random(), 0.65) * 15;
    const angle = Math.random() * Math.PI * 2;
    dustPositions[i * 3] = Math.cos(angle) * radius;
    dustPositions[i * 3 + 1] = -0.6 + Math.random() * 9;
    dustPositions[i * 3 + 2] = Math.sin(angle) * radius;
    dustSizes[i] = 0.7 + Math.random() * 2.4;
    dustSeeds[i] = Math.random();
  }
  dustGeometry.setAttribute("position", new THREE.BufferAttribute(dustPositions, 3));
  dustGeometry.setAttribute("aSize", new THREE.BufferAttribute(dustSizes, 1));
  dustGeometry.setAttribute("aSeed", new THREE.BufferAttribute(dustSeeds, 1));

  const dustMaterial = new THREE.ShaderMaterial({
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    uniforms: {
      uTime: { value: 0 },
      uA: { value: paletteA.clone() },
      uB: { value: paletteB.clone() },
      uPixelRatio: { value: Math.min(window.devicePixelRatio || 1, 2) },
    },
    vertexShader: /* glsl */ `
      attribute float aSize;
      attribute float aSeed;
      uniform float uTime;
      uniform float uPixelRatio;
      varying float vSeed;
      varying float vFade;
      void main() {
        vec3 p = position;
        p.y += sin(uTime * 0.16 + aSeed * 6.283) * 0.35;
        p.x += cos(uTime * 0.11 + aSeed * 6.283) * 0.22;
        vec4 mv = modelViewMatrix * vec4(p, 1.0);
        gl_PointSize = aSize * uPixelRatio * (170.0 / max(0.001, -mv.z));
        gl_Position = projectionMatrix * mv;
        vSeed = aSeed;
        vFade = 0.4 + 0.6 * (0.5 + 0.5 * sin(uTime * 0.9 + aSeed * 22.0));
      }
    `,
    fragmentShader: /* glsl */ `
      uniform vec3 uA;
      uniform vec3 uB;
      varying float vSeed;
      varying float vFade;
      void main() {
        float d = length(gl_PointCoord - 0.5);
        float alpha = smoothstep(0.5, 0.0, d);
        alpha *= alpha * vFade;
        vec3 col = mix(uA, uB, vSeed);
        gl_FragColor = vec4(col, alpha * 0.7);
      }
    `,
  });
  const dust = new THREE.Points(dustGeometry, dustMaterial);
  dust.frustumCulled = false;
  scene.add(dust);

  // Lighting: hot key, cold rim, violet fill.
  const ambient = new THREE.AmbientLight(0xffffff, 0.35);
  scene.add(ambient);

  const key = new THREE.SpotLight(0xffffff, 320, 40, 0.62, 0.95, 1.6);
  key.position.set(5, 8, 6);
  key.target.position.set(0, 1.5, 0);
  scene.add(key, key.target);

  const rim = new THREE.DirectionalLight(0xffffff, 2.1);
  rim.position.set(-6, 5, -5);
  scene.add(rim);

  const fill = new THREE.PointLight(0xffffff, 26, 14, 2);
  fill.position.set(0, 1.4, 3.4);
  scene.add(fill);

  const under = new THREE.PointLight(0xffffff, 18, 12, 2);
  under.position.set(0, 0.25, 1.2);
  scene.add(under);

  function update(time, dt, palette) {
    sky.rotation.y = time * 0.008;
    gridMaterial.uniforms.uTime.value = time;
    gridMaterial.uniforms.uA.value.copy(palette.a);
    gridMaterial.uniforms.uB.value.copy(palette.b);
    dustMaterial.uniforms.uTime.value = time;
    dustMaterial.uniforms.uA.value.copy(palette.a);
    dustMaterial.uniforms.uB.value.copy(palette.b);

    mirror.material.uniforms.color.value.copy(palette.bg).lerp(palette.c, 0.55);

    daisRimMaterial.color.copy(palette.a);
    daisInnerMaterial.color.copy(palette.b);
    daisRimMaterial.opacity = 0.65 + Math.sin(time * 1.4) * 0.15;

    rings.forEach((ring) => {
      const data = ring.userData;
      ring.rotation.z += dt * data.speed;
      ring.rotation.y = data.tilt.y + Math.sin(time * 0.3 + data.index) * 0.12;
      data.material.color.copy(palette[data.colorKey]);
      data.material.opacity = 0.38 + Math.sin(time * 1.1 + data.index * 2) * 0.12;
      data.gemMaterial.color.copy(data.colorKey === "b" ? palette.a : palette.b);
    });

    shards.forEach((shard, index) => {
      const data = shard.userData;
      shard.position.y = data.baseY + Math.sin(time * 0.6 + data.phase) * 0.16;
      shard.rotation.x += dt * data.speed * 0.5;
      shard.rotation.y += dt * data.speed * 0.8;
      data.angle += dt * data.orbit;
      shard.position.x = Math.cos(data.angle) * data.radius;
      shard.position.z = Math.sin(data.angle) * data.radius;
      const pulse = 0.85 + Math.sin(time * 1.2 + index) * 0.15;
      shard.scale.x = 0.8 * pulse;
      shard.scale.z = 0.8 * pulse;
    });

    key.color.copy(palette.a);
    rim.color.copy(palette.b);
    fill.color.copy(palette.c);
    under.color.copy(palette.a);
    scene.fog.color.copy(palette.bg);
  }

  function setTheme(palette) {
    rebuildEnvironment(palette.a, palette.b, palette.c);
  }

  function setQuality(next) {
    dustMaterial.uniforms.uPixelRatio.value = next.pixelRatio;
  }

  function dispose() {
    pmrem.dispose();
    envTarget?.dispose();
  }

  return {
    update,
    setTheme,
    setQuality,
    dispose,
    mirror,
    rings,
    shards,
    dust,
    lights: { ambient, key, rim, fill, under },
  };
}

import * as THREE from "three";

export function glowTexture() {
  const canvas = document.createElement("canvas");
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext("2d");
  const gradient = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
  gradient.addColorStop(0, "rgba(255,255,255,1)");
  gradient.addColorStop(0.22, "rgba(255,255,255,0.85)");
  gradient.addColorStop(0.5, "rgba(255,255,255,0.26)");
  gradient.addColorStop(1, "rgba(255,255,255,0)");
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, 128, 128);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.needsUpdate = true;
  return texture;
}

function limb(a, b, radiusA, radiusB, material, radialSegments = 14) {
  const direction = new THREE.Vector3().subVectors(b, a);
  const length = direction.length();
  const geometry = new THREE.CylinderGeometry(radiusB, radiusA, length, radialSegments, 1, false);
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.copy(a).add(b).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), direction.normalize());
  return mesh;
}

function ball(position, radius, scale, material) {
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(radius, 24, 18), material);
  mesh.position.copy(position);
  if (scale) mesh.scale.copy(scale);
  return mesh;
}

function sprite(texture, color, scale, opacity = 1) {
  const material = new THREE.SpriteMaterial({
    map: texture,
    color,
    transparent: true,
    opacity,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    depthTest: true,
  });
  const item = new THREE.Sprite(material);
  item.scale.set(scale, scale, 1);
  return item;
}

export function createGoddess(palette, quality) {
  const root = new THREE.Group();
  root.position.y = 0.02;
  const body = new THREE.Group();
  root.add(body);

  const glow = glowTexture();

  const chrome = new THREE.MeshPhysicalMaterial({
    color: 0xffeaf8,
    metalness: 1,
    roughness: 0.1,
    envMapIntensity: 2.3,
    clearcoat: 1,
    clearcoatRoughness: 0.07,
    iridescence: 1,
    iridescenceIOR: 1.75,
    iridescenceThicknessRange: [110, 640],
  });

  const hairMaterial = new THREE.MeshStandardMaterial({
    color: 0x150020,
    metalness: 0.92,
    roughness: 0.24,
    emissive: 0x22002e,
    emissiveIntensity: 0.7,
    envMapIntensity: 1.5,
  });

  const hairAccent = new THREE.MeshStandardMaterial({
    color: 0x4a003f,
    metalness: 0.8,
    roughness: 0.3,
    emissive: palette.a.clone().multiplyScalar(0.5),
    emissiveIntensity: 1.2,
    envMapIntensity: 1.4,
  });

  // Torso — a lathed chrome silhouette with a pinched waist and flared hips.
  const profile = [
    [0.002, 0.83],
    [0.23, 0.845],
    [0.315, 0.9],
    [0.365, 0.99],
    [0.372, 1.09],
    [0.335, 1.23],
    [0.298, 1.39],
    [0.318, 1.54],
    [0.362, 1.69],
    [0.36, 1.8],
    [0.312, 1.9],
    [0.226, 1.985],
    [0.118, 2.03],
    [0.068, 2.06],
    [0.062, 2.1],
  ].map(([x, y]) => new THREE.Vector2(x, y));
  const torso = new THREE.Mesh(new THREE.LatheGeometry(profile, 64), chrome);
  torso.scale.z = 0.79;
  body.add(torso);

  const pelvis = ball(new THREE.Vector3(0, 0.99, -0.02), 0.33, new THREE.Vector3(1.02, 0.74, 0.84), chrome);
  body.add(pelvis);

  [-1, 1].forEach((side) => {
    body.add(
      ball(
        new THREE.Vector3(0.135 * side, 1.715, 0.155),
        0.132,
        new THREE.Vector3(1, 0.96, 0.8),
        chrome
      )
    );
    body.add(
      ball(
        new THREE.Vector3(0.288 * side, 1.985, 0),
        0.096,
        new THREE.Vector3(1.08, 0.9, 1),
        chrome
      )
    );
  });

  // Neck and head.
  body.add(limb(new THREE.Vector3(0, 2.0, 0), new THREE.Vector3(0, 2.18, 0), 0.08, 0.062, chrome));
  const head = ball(new THREE.Vector3(0, 2.355, 0.008), 0.185, new THREE.Vector3(0.88, 1.08, 0.94), chrome);
  body.add(head);
  body.add(ball(new THREE.Vector3(0, 2.283, 0.038), 0.122, new THREE.Vector3(0.8, 0.74, 0.92), chrome));

  // Eyes that glow like reactor cores.
  const eyeMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff });
  const eyeSprites = [];
  [-1, 1].forEach((side) => {
    const eye = ball(new THREE.Vector3(0.063 * side, 2.373, 0.166), 0.021, new THREE.Vector3(1.35, 0.75, 0.6), eyeMaterial);
    body.add(eye);
    const halo = sprite(glow, palette.a.clone(), 0.13, 0.95);
    halo.position.set(0.063 * side, 2.373, 0.19);
    body.add(halo);
    eyeSprites.push(halo);
  });

  // Hair cap and sculpted face frame.
  const cap = ball(new THREE.Vector3(0, 2.362, -0.05), 0.205, new THREE.Vector3(1.01, 1.03, 0.88), hairMaterial);
  body.add(cap);
  [-1, 1].forEach((side) => {
    body.add(
      ball(
        new THREE.Vector3(0.163 * side, 2.29, -0.028),
        0.1,
        new THREE.Vector3(0.72, 1.35, 0.9),
        hairMaterial
      )
    );
  });

  const hairPivot = new THREE.Group();
  hairPivot.position.set(0, 2.36, 0);
  body.add(hairPivot);

  const strandCount = quality.mobile ? 16 : 24;
  for (let i = 0; i < strandCount; i += 1) {
    const t = i / (strandCount - 1);
    const theta = 1.16 + t * (Math.PI * 2 - 2.32);
    const startRadius = 0.18;
    const start = new THREE.Vector3(
      Math.sin(theta) * startRadius,
      2.39 + (Math.random() - 0.5) * 0.13,
      Math.cos(theta) * startRadius - 0.035
    );
    const p1 = new THREE.Vector3(
      Math.sin(theta) * 0.255 + Math.sin(theta * 3.1) * 0.03,
      2.24 + (Math.random() - 0.5) * 0.12,
      Math.cos(theta) * 0.245 - 0.04
    );
    const p2 = new THREE.Vector3(
      Math.sin(theta) * (0.38 + Math.random() * 0.12) + Math.sin(theta * 2.3) * 0.07,
      1.82 + (Math.random() - 0.5) * 0.16,
      Math.cos(theta) * (0.34 + Math.random() * 0.12) - 0.05
    );
    const end = new THREE.Vector3(
      Math.sin(theta) * (0.46 + Math.random() * 0.28) + Math.sin(theta * 1.7) * 0.1,
      1.02 + Math.random() * 0.46,
      Math.cos(theta) * (0.38 + Math.random() * 0.22) - 0.02
    );
    const points = [start, p1, p2, end].map((point) => point.clone().sub(hairPivot.position));
    const curve = new THREE.CatmullRomCurve3(points, false, "catmullrom", 0.45);
    const material = i % 5 === 0 ? hairAccent : hairMaterial;
    const strand = new THREE.Mesh(
      new THREE.TubeGeometry(curve, 28, 0.013 + Math.random() * 0.016, 5, false),
      material
    );
    hairPivot.add(strand);
  }

  // Fringe.
  for (let i = 0; i < 6; i += 1) {
    const side = i % 2 === 0 ? -1 : 1;
    const start = new THREE.Vector3(side * 0.02, 2.52, 0.08);
    const end = new THREE.Vector3(side * (0.08 + Math.random() * 0.1), 2.29 + Math.random() * 0.07, 0.165);
    const mid = new THREE.Vector3(side * (0.1 + Math.random() * 0.06), 2.44, 0.15);
    const curve = new THREE.CatmullRomCurve3(
      [start, mid, end].map((point) => point.clone().sub(hairPivot.position)),
      false,
      "catmullrom",
      0.5
    );
    const strand = new THREE.Mesh(new THREE.TubeGeometry(curve, 16, 0.009 + Math.random() * 0.006, 5, false), hairMaterial);
    hairPivot.add(strand);
  }

  // Arms: one conjures, one lets a relic hover.
  const rightShoulder = new THREE.Vector3(0.295, 1.975, 0);
  const rightElbow = new THREE.Vector3(0.59, 2.225, 0.09);
  const rightWrist = new THREE.Vector3(0.735, 2.515, 0.225);
  const rightPalm = new THREE.Vector3(0.775, 2.605, 0.27);
  body.add(limb(rightShoulder, rightElbow, 0.078, 0.057, chrome));
  body.add(limb(rightElbow, rightWrist, 0.057, 0.042, chrome));
  body.add(ball(rightElbow, 0.058, null, chrome));
  body.add(ball(rightWrist, 0.042, null, chrome));
  const rightHand = ball(rightPalm, 0.055, new THREE.Vector3(1.15, 1.25, 0.65), chrome);
  rightHand.rotation.z = -0.4;
  body.add(rightHand);
  for (let i = 0; i < 3; i += 1) {
    const base = new THREE.Vector3(rightPalm.x + 0.005 + i * 0.018, rightPalm.y + 0.045, rightPalm.z + 0.012);
    const tip = new THREE.Vector3(base.x + 0.006 + i * 0.01, base.y + 0.075, base.z + 0.018);
    body.add(limb(base, tip, 0.011, 0.005, chrome, 6));
  }

  const leftShoulder = new THREE.Vector3(-0.295, 1.975, 0);
  const leftElbow = new THREE.Vector3(-0.525, 1.675, 0.08);
  const leftWrist = new THREE.Vector3(-0.535, 1.345, 0.175);
  const leftPalm = new THREE.Vector3(-0.52, 1.265, 0.215);
  body.add(limb(leftShoulder, leftElbow, 0.078, 0.057, chrome));
  body.add(limb(leftElbow, leftWrist, 0.057, 0.042, chrome));
  body.add(ball(leftElbow, 0.058, null, chrome));
  body.add(ball(leftWrist, 0.042, null, chrome));
  body.add(ball(leftPalm, 0.052, new THREE.Vector3(1.1, 1.3, 0.65), chrome));
  for (let i = 0; i < 3; i += 1) {
    const base = new THREE.Vector3(leftPalm.x - 0.012 - i * 0.016, leftPalm.y - 0.04, leftPalm.z + 0.01);
    const tip = new THREE.Vector3(base.x - 0.004 - i * 0.008, base.y - 0.06, base.z + 0.016);
    body.add(limb(base, tip, 0.01, 0.005, chrome, 6));
  }

  // Legs and heels, visible through the veil.
  [-1, 1].forEach((side) => {
    const hip = new THREE.Vector3(0.155 * side, 0.965, 0);
    const knee = new THREE.Vector3(0.16 * side, 0.535, 0.015);
    const ankle = new THREE.Vector3(0.145 * side, 0.105, 0.035);
    body.add(limb(hip, knee, 0.105, 0.07, chrome));
    body.add(limb(knee, ankle, 0.065, 0.042, chrome));
    body.add(ball(knee, 0.068, null, chrome));
    body.add(ball(ankle, 0.042, null, chrome));
    const foot = ball(new THREE.Vector3(0.145 * side, 0.055, 0.1), 0.07, new THREE.Vector3(0.95, 0.5, 1.9), chrome);
    body.add(foot);
    body.add(limb(new THREE.Vector3(0.145 * side, 0.05, -0.045), new THREE.Vector3(0.145 * side, 0.0, -0.06), 0.014, 0.008, chrome, 6));
  });

  // Belt.
  const beltMaterial = new THREE.MeshBasicMaterial({
    color: palette.a.clone(),
    transparent: true,
    opacity: 0.9,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  });
  const belt = new THREE.Mesh(new THREE.TorusGeometry(0.315, 0.009, 6, 96), beltMaterial);
  belt.rotation.x = Math.PI / 2;
  belt.position.y = 1.0;
  belt.scale.z = 0.86;
  body.add(belt);

  // Flowing iridescent gown.
  const gownUniforms = {
    uTime: { value: 0 },
    uA: { value: palette.a.clone() },
    uB: { value: palette.b.clone() },
    uC: { value: palette.c.clone() },
  };
  const gownMaterial = new THREE.ShaderMaterial({
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
    uniforms: gownUniforms,
    vertexShader: /* glsl */ `
      uniform float uTime;
      varying vec2 vUv;
      varying vec3 vNormal;
      varying vec3 vView;
      void main() {
        vUv = uv;
        vec3 p = position;
        float t = uv.y;
        float wave = sin(p.x * 2.2 + uTime * 1.05) * 0.035 + cos(p.z * 2.7 - uTime * 0.8) * 0.035;
        p += normal * wave * (0.35 + 0.65 * t);
        vec4 mv = modelViewMatrix * vec4(p, 1.0);
        vNormal = normalize(normalMatrix * normal);
        vView = normalize(-mv.xyz);
        gl_Position = projectionMatrix * mv;
      }
    `,
    fragmentShader: /* glsl */ `
      uniform float uTime;
      uniform vec3 uA;
      uniform vec3 uB;
      uniform vec3 uC;
      varying vec2 vUv;
      varying vec3 vNormal;
      varying vec3 vView;
      void main() {
        float fres = pow(1.0 - abs(dot(vNormal, vView)), 2.1);
        float band = sin((vUv.y * 5.2 - uTime * 0.35 + fres * 1.8) * 3.14159);
        vec3 col = mix(uA, uB, smoothstep(-1.0, 1.0, band));
        col = mix(col, uC, fres * 0.65);
        float sparkle = pow(max(0.0, sin(vUv.x * 180.0 + vUv.y * 30.0 - uTime * 1.6)), 22.0);
        col += sparkle * 0.9;
        float alpha = 0.15 + 0.46 * fres + 0.12 * vUv.y;
        gl_FragColor = vec4(col, alpha);
      }
    `,
  });

  const gownSegments = quality.mobile ? 64 : 96;
  const gownRows = 18;
  const gownPositions = [];
  const gownUvs = [];
  const gownIndices = [];
  for (let i = 0; i <= gownRows; i += 1) {
    const t = i / gownRows;
    const y = 0.995 - 0.865 * t;
    const baseRadius = 0.3 + 0.57 * Math.pow(t, 1.35);
    for (let j = 0; j <= gownSegments; j += 1) {
      const theta = (j / gownSegments) * Math.PI * 2;
      const wave = Math.sin(theta * 7 + t * 4.2) * 0.045 * t + Math.sin(theta * 3 - t * 6) * 0.02 * t;
      const radius = baseRadius + wave;
      const x = Math.sin(theta) * radius;
      const z = Math.cos(theta) * radius * 0.86;
      const yy = y + Math.sin(theta * 9 + t * 3) * 0.018 * t;
      gownPositions.push(x, yy, z);
      gownUvs.push(j / gownSegments, t);
    }
  }
  for (let i = 0; i < gownRows; i += 1) {
    for (let j = 0; j < gownSegments; j += 1) {
      const a = i * (gownSegments + 1) + j;
      const b = a + gownSegments + 1;
      gownIndices.push(a, b, a + 1, b, b + 1, a + 1);
    }
  }
  const gownGeometry = new THREE.BufferGeometry();
  gownGeometry.setAttribute("position", new THREE.Float32BufferAttribute(gownPositions, 3));
  gownGeometry.setAttribute("uv", new THREE.Float32BufferAttribute(gownUvs, 2));
  gownGeometry.setIndex(gownIndices);
  gownGeometry.computeVertexNormals();
  const gown = new THREE.Mesh(gownGeometry, gownMaterial);
  gown.renderOrder = 2;
  body.add(gown);

  // Silk ribbons orbiting the gown.
  const ribbons = new THREE.Group();
  const ribbonCount = quality.mobile ? 4 : 7;
  for (let i = 0; i < ribbonCount; i += 1) {
    const angle = (i / ribbonCount) * Math.PI * 2;
    const ribbon = new THREE.Mesh(new THREE.PlaneGeometry(0.17, 1.75, 1, 20), gownMaterial);
    ribbon.position.set(Math.sin(angle) * 0.55, 0.42, Math.cos(angle) * 0.5);
    ribbon.rotation.y = angle;
    ribbon.rotation.z = (Math.random() - 0.5) * 0.25;
    ribbon.rotation.x = 0.08;
    ribbon.renderOrder = 3;
    ribbons.add(ribbon);
  }
  body.add(ribbons);

  // Crown of chrome shards.
  const crown = new THREE.Group();
  crown.position.y = 2.52;
  for (let i = 0; i < 7; i += 1) {
    const angle = (i / 7) * Math.PI * 2;
    const height = 0.17 + (i === 0 ? 0.12 : Math.random() * 0.1);
    const shard = new THREE.Mesh(new THREE.ConeGeometry(0.035, height, 4), chrome);
    shard.position.set(Math.sin(angle) * 0.185, height * 0.42, Math.cos(angle) * 0.185);
    shard.rotation.x = Math.cos(angle) * 0.32;
    shard.rotation.z = -Math.sin(angle) * 0.32;
    crown.add(shard);
  }
  const crownBand = new THREE.Mesh(new THREE.TorusGeometry(0.19, 0.006, 6, 80), beltMaterial);
  crownBand.rotation.x = Math.PI / 2;
  crown.add(crownBand);
  body.add(crown);

  // Halo rings.
  const haloMaterial = new THREE.MeshBasicMaterial({
    color: palette.a.clone(),
    transparent: true,
    opacity: 0.85,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  });
  const haloMaterial2 = haloMaterial.clone();
  haloMaterial2.color = palette.b.clone();
  haloMaterial2.opacity = 0.55;
  const halo = new THREE.Group();
  halo.position.set(0, 2.42, -0.15);
  const haloInner = new THREE.Mesh(new THREE.TorusGeometry(0.335, 0.007, 6, 120), haloMaterial);
  const haloOuter = new THREE.Mesh(new THREE.TorusGeometry(0.465, 0.004, 6, 120), haloMaterial2);
  haloOuter.rotation.z = 0.5;
  halo.add(haloInner, haloOuter);
  body.add(halo);

  // Chest gem.
  const gemMaterial = new THREE.MeshBasicMaterial({ color: palette.a.clone() });
  const chestGem = new THREE.Mesh(new THREE.OctahedronGeometry(0.062, 0), gemMaterial);
  chestGem.position.set(0, 1.835, 0.285);
  chestGem.rotation.z = 0.2;
  body.add(chestGem);
  const chestGlow = sprite(glow, palette.a.clone(), 0.5, 0.65);
  chestGlow.position.set(0, 1.835, 0.27);
  body.add(chestGlow);

  // Shoulder relics.
  const shoulderRelics = [];
  [-1, 1].forEach((side) => {
    const relic = new THREE.Mesh(new THREE.OctahedronGeometry(0.055, 0), chrome);
    relic.scale.set(0.7, 2.8, 0.7);
    relic.position.set(0.43 * side, 2.16, 0.02);
    body.add(relic);
    shoulderRelics.push(relic);
  });

  // The conjured orb.
  const orb = new THREE.Group();
  orb.position.set(0.785, 2.77, 0.3);
  const orbCoreMaterial = new THREE.MeshBasicMaterial({ color: palette.a.clone() });
  const orbCore = new THREE.Mesh(new THREE.SphereGeometry(0.055, 20, 14), orbCoreMaterial);
  const orbGlow = sprite(glow, palette.a.clone(), 0.95, 0.9);
  const orbRing = new THREE.Mesh(new THREE.TorusGeometry(0.105, 0.004, 5, 64), haloMaterial);
  orbRing.rotation.x = 1.1;
  const orbRing2 = new THREE.Mesh(new THREE.TorusGeometry(0.13, 0.003, 5, 64), haloMaterial2);
  orbRing2.rotation.set(0.4, 0.8, 0.2);
  const orbLight = new THREE.PointLight(palette.a.clone(), 9, 4.5, 2);
  orb.add(orbCore, orbGlow, orbRing, orbRing2, orbLight);
  body.add(orb);

  // A small relic above the open left palm.
  const leftRelic = new THREE.Mesh(new THREE.OctahedronGeometry(0.055, 0), gemMaterial);
  leftRelic.position.set(-0.53, 1.4, 0.25);
  leftRelic.scale.set(0.8, 1.6, 0.8);
  body.add(leftRelic);
  const leftRelicGlow = sprite(glow, palette.b.clone(), 0.4, 0.55);
  leftRelicGlow.position.copy(leftRelic.position);
  body.add(leftRelicGlow);

  // Backlight aura.
  const aura = sprite(glow, palette.c.clone(), 2.4, 0.24);
  aura.position.set(0, 2.0, -0.35);
  body.add(aura);

  let pulse = 0;
  let spin = 0;
  let spinVelocity = 0;

  function update(time, dt, currentPalette) {
    root.position.y = 0.02 + Math.sin(time * 0.8) * 0.026;

    spinVelocity *= Math.pow(0.2, dt);
    spin += spinVelocity * dt;
    pulse *= Math.pow(0.08, dt);

    body.rotation.y = Math.sin(time * 0.24) * 0.055 + spin;
    const scale = 1 + Math.sin(time * 1.2) * 0.004 + pulse * 0.08;
    body.scale.setScalar(scale);

    hairPivot.rotation.z = Math.sin(time * 0.52) * 0.024;
    hairPivot.rotation.x = Math.sin(time * 0.37) * 0.014;
    hairPivot.rotation.y = Math.sin(time * 0.29) * 0.032;

    gownUniforms.uTime.value = time;
    gownUniforms.uA.value.copy(currentPalette.a);
    gownUniforms.uB.value.copy(currentPalette.b);
    gownUniforms.uC.value.copy(currentPalette.c);
    ribbons.rotation.y = Math.sin(time * 0.4) * 0.08;

    crown.rotation.y = time * 0.14;
    crown.position.y = 2.52 + Math.sin(time * 1.1) * 0.012;

    halo.rotation.z = time * 0.35;
    halo.rotation.y = Math.sin(time * 0.5) * 0.18;
    haloInner.rotation.z = -time * 0.2;
    haloOuter.rotation.z = 0.5 + time * 0.28;

    haloMaterial.color.copy(currentPalette.a);
    haloMaterial2.color.copy(currentPalette.b);
    haloMaterial.opacity = 0.65 + Math.sin(time * 1.6) * 0.2;
    haloMaterial2.opacity = 0.4 + Math.sin(time * 1.2 + 1) * 0.15;

    beltMaterial.color.copy(currentPalette.a);
    gemMaterial.color.copy(currentPalette.a).lerp(new THREE.Color(0xffffff), 0.25);
    chestGem.rotation.y = time * 0.9;
    chestGem.position.y = 1.835 + Math.sin(time * 1.4) * 0.012;
    chestGlow.position.y = chestGem.position.y;
    chestGlow.material.color.copy(currentPalette.a);
    chestGlow.material.opacity = 0.5 + Math.sin(time * 1.8) * 0.16;

    shoulderRelics.forEach((relic, index) => {
      relic.position.y = 2.16 + Math.sin(time * 0.9 + index * 2) * 0.055;
      relic.rotation.y = time * 0.5 + index;
    });

    const orbPulse = 1 + Math.sin(time * 2.4) * 0.09;
    orbCore.scale.setScalar(orbPulse);
    orbGlow.scale.setScalar(0.9 * orbPulse);
    orbGlow.material.color.copy(currentPalette.a);
    orbCoreMaterial.color.copy(currentPalette.a).lerp(new THREE.Color(0xffffff), 0.35);
    orbRing.rotation.z = time * 0.8;
    orbRing2.rotation.z = -time * 0.6;
    orbLight.color.copy(currentPalette.a);
    orbLight.intensity = 8 + Math.sin(time * 2.4) * 2;

    leftRelic.rotation.y = -time * 0.7;
    leftRelic.position.y = 1.4 + Math.sin(time * 1.3) * 0.03;
    leftRelicGlow.position.y = leftRelic.position.y;
    leftRelicGlow.material.color.copy(currentPalette.b);
    leftRelicGlow.material.opacity = 0.45 + Math.sin(time * 1.7) * 0.14;

    eyeSprites.forEach((eyeGlow) => {
      eyeGlow.material.color.copy(currentPalette.a).lerp(new THREE.Color(0xffffff), 0.4);
      eyeGlow.material.opacity = 0.75 + Math.sin(time * 3.1) * 0.2;
    });
    eyeMaterial.color.copy(currentPalette.a).lerp(new THREE.Color(0xffffff), 0.55);

    aura.material.color.copy(currentPalette.c);
    aura.material.opacity = 0.18 + Math.sin(time * 0.9) * 0.05;
    aura.scale.setScalar(2.4 + Math.sin(time * 0.7) * 0.15);

    hairAccent.emissive.copy(currentPalette.a).multiplyScalar(0.55);
  }

  return {
    root,
    body,
    orb,
    gown,
    update,
    kick(amount = 1) {
      pulse = Math.min(1.4, pulse + amount);
    },
    spin(amount = 2.5) {
      spinVelocity += amount;
    },
    setPalette(currentPalette) {
      hairAccent.emissive.copy(currentPalette.a).multiplyScalar(0.55);
    },
  };
}

import * as THREE from "three";
import { glowTexture } from "./figure.js";

const CENTER = new THREE.Vector3(0, 1.5, 0);
const EASE_OUT = (t) => 1 - Math.pow(1 - t, 3);
const EASE_IN = (t) => t * t * t;

export class SoulField {
  constructor(scene, palette, quality) {
    this.scene = scene;
    this.max = quality.mobile ? 90 : 170;
    this.time = 0;
    this.souls = [];
    this.geometry = new THREE.BufferGeometry();
    this.positions = new Float32Array(this.max * 3);
    this.colors = new Float32Array(this.max * 3);
    this.sizes = new Float32Array(this.max);
    this.phases = new Float32Array(this.max);

    this.geometry.setAttribute("position", new THREE.BufferAttribute(this.positions, 3).setUsage(THREE.DynamicDrawUsage));
    this.geometry.setAttribute("aColor", new THREE.BufferAttribute(this.colors, 3).setUsage(THREE.DynamicDrawUsage));
    this.geometry.setAttribute("aSize", new THREE.BufferAttribute(this.sizes, 1).setUsage(THREE.DynamicDrawUsage));
    this.geometry.setAttribute("aPhase", new THREE.BufferAttribute(this.phases, 1).setUsage(THREE.DynamicDrawUsage));

    this.material = new THREE.ShaderMaterial({
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      uniforms: {
        uPixelRatio: { value: Math.min(window.devicePixelRatio || 1, 2) },
      },
      vertexShader: /* glsl */ `
        attribute vec3 aColor;
        attribute float aSize;
        attribute float aPhase;
        uniform float uPixelRatio;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_Position = projectionMatrix * mv;
          gl_PointSize = aSize * uPixelRatio * (58.0 / max(0.001, -mv.z));
          vColor = aColor;
          vAlpha = 0.72 + 0.28 * sin(aPhase * 31.0);
        }
      `,
      fragmentShader: /* glsl */ `
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vec2 c = gl_PointCoord - 0.5;
          float d = length(c);
          float core = pow(smoothstep(0.5, 0.0, d), 2.4);
          float star = max(0.0, 1.0 - abs(c.x) * 15.0) * max(0.0, 1.0 - abs(c.y) * 2.4)
                     + max(0.0, 1.0 - abs(c.y) * 15.0) * max(0.0, 1.0 - abs(c.x) * 2.4);
          star *= smoothstep(0.5, 0.0, d);
          float alpha = (core + star * 0.55) * vAlpha;
          if (alpha < 0.004) discard;
          gl_FragColor = vec4(vColor * (1.0 + star * 1.4), alpha);
        }
      `,
    });

    this.points = new THREE.Points(this.geometry, this.material);
    this.points.frustumCulled = false;
    this.points.renderOrder = 5;
    scene.add(this.points);

    for (let i = 0; i < this.max; i += 1) {
      this.souls.push({
        active: false,
        birth: 0,
        start: new THREE.Vector3(),
        radius: 1,
        baseY: 1.5,
        phase: 0,
        speed: 0.2,
        targetSize: 1,
        color: new THREE.Color(),
        dying: false,
        deathAt: 0,
        deathStart: new THREE.Vector3(),
        deathTarget: new THREE.Vector3(),
      });
    }

    this.recolor(palette);
  }

  pickColor(palette) {
    const roll = Math.random();
    if (roll < 0.42) return palette.a;
    if (roll < 0.76) return palette.b;
    if (roll < 0.92) return palette.c;
    return new THREE.Color(0xffffff);
  }

  spawn(count, origin, palette) {
    for (let n = 0; n < count; n += 1) {
      let slot = this.souls.find((soul) => !soul.active);
      if (!slot) {
        slot = this.souls.reduce((oldest, soul) => (soul.birth < oldest.birth ? soul : oldest), this.souls[0]);
      }
      const index = this.souls.indexOf(slot);
      const angle = Math.random() * Math.PI * 2;
      slot.active = true;
      slot.dying = false;
      slot.birth = this.time + Math.random() * 0.18;
      slot.start.copy(origin).add(
        new THREE.Vector3((Math.random() - 0.5) * 0.18, (Math.random() - 0.5) * 0.18, (Math.random() - 0.5) * 0.18)
      );
      slot.radius = 0.85 + Math.random() * 1.85;
      slot.baseY = 0.4 + Math.random() * 2.75;
      slot.phase = angle;
      slot.speed = (0.12 + Math.random() * 0.36) * (Math.random() < 0.5 ? -1 : 1);
      slot.targetSize = 0.55 + Math.random() * 1.05;
      slot.color.copy(this.pickColor(palette));
      slot.deathStart.set(0, 0, 0);
      slot.deathTarget.set(0, 0, 0);

      this.colors[index * 3] = slot.color.r;
      this.colors[index * 3 + 1] = slot.color.g;
      this.colors[index * 3 + 2] = slot.color.b;
      this.phases[index] = slot.phase;
      this.sizes[index] = 0;
      this.positions[index * 3] = slot.start.x;
      this.positions[index * 3 + 1] = slot.start.y;
      this.positions[index * 3 + 2] = slot.start.z;
    }
    this.geometry.attributes.aColor.needsUpdate = true;
    this.geometry.attributes.aPhase.needsUpdate = true;
  }

  destroy() {
    this.souls.forEach((soul) => {
      if (!soul.active || soul.dying) return;
      soul.dying = true;
      soul.deathAt = this.time + Math.random() * 0.4;
      const index = this.souls.indexOf(soul);
      soul.deathStart.set(this.positions[index * 3], this.positions[index * 3 + 1], this.positions[index * 3 + 2]);
      soul.deathTarget.copy(CENTER).add(
        new THREE.Vector3((Math.random() - 0.5) * 0.16, (Math.random() - 0.5) * 0.16, (Math.random() - 0.5) * 0.16)
      );
    });
  }

  recolor(palette) {
    this.souls.forEach((soul, index) => {
      if (!soul.active) return;
      soul.color.copy(this.pickColor(palette));
      this.colors[index * 3] = soul.color.r;
      this.colors[index * 3 + 1] = soul.color.g;
      this.colors[index * 3 + 2] = soul.color.b;
    });
    this.geometry.attributes.aColor.needsUpdate = true;
  }

  update(time) {
    this.time = time;
    for (let i = 0; i < this.max; i += 1) {
      const soul = this.souls[i];
      if (!soul.active) {
        this.sizes[i] = 0;
        continue;
      }

      if (soul.dying) {
        const progress = Math.min(1, Math.max(0, (time - soul.deathAt) / 0.8));
        if (progress >= 1) {
          soul.active = false;
          this.sizes[i] = 0;
          continue;
        }
        const eased = EASE_IN(progress);
        const spiral = (1 - progress) * 0.6;
        const angle = soul.phase + progress * 14;
        this.positions[i * 3] = soul.deathStart.x + (soul.deathTarget.x - soul.deathStart.x) * eased + Math.cos(angle) * spiral;
        this.positions[i * 3 + 1] = soul.deathStart.y + (soul.deathTarget.y - soul.deathStart.y) * eased + Math.sin(angle * 1.3) * spiral * 0.5;
        this.positions[i * 3 + 2] = soul.deathStart.z + (soul.deathTarget.z - soul.deathStart.z) * eased + Math.sin(angle) * spiral;
        this.sizes[i] = soul.targetSize * (1 - progress) * (0.4 + Math.sin(progress * Math.PI) * 0.6);
        continue;
      }

      const age = time - soul.birth;
      if (age < 0) {
        this.sizes[i] = 0;
        continue;
      }
      const appear = EASE_OUT(Math.min(1, age / 0.85));
      const angle = soul.phase + time * soul.speed;
      const radius = soul.radius * (0.7 + 0.3 * appear);
      const targetX = Math.cos(angle) * radius;
      const targetZ = Math.sin(angle) * radius * 0.86;
      const targetY = soul.baseY + Math.sin(time * 0.75 + soul.phase * 2.2) * 0.17;
      this.positions[i * 3] = soul.start.x + (targetX - soul.start.x) * appear;
      this.positions[i * 3 + 1] = soul.start.y + (targetY - soul.start.y) * appear;
      this.positions[i * 3 + 2] = soul.start.z + (targetZ - soul.start.z) * appear;
      const fadeIn = Math.min(1, age / 0.3);
      this.sizes[i] = soul.targetSize * appear * (0.85 + Math.sin(time * 2.4 + soul.phase * 5) * 0.15) * fadeIn;
    }
    this.geometry.attributes.position.needsUpdate = true;
    this.geometry.attributes.aSize.needsUpdate = true;
  }

  count() {
    return this.souls.reduce((total, soul) => total + (soul.active && !soul.dying ? 1 : 0), 0);
  }

  clear() {
    this.souls.forEach((soul) => {
      soul.active = false;
    });
    this.sizes.fill(0);
    this.geometry.attributes.aSize.needsUpdate = true;
  }
}

export class Shockwaves {
  constructor(scene) {
    this.scene = scene;
    this.waves = [];
  }

  fire(position, palette, power = 1) {
    const material = new THREE.MeshBasicMaterial({
      color: palette.a.clone(),
      transparent: true,
      opacity: 0.9,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      side: THREE.DoubleSide,
    });
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.9, 1.0, 128), material);
    ring.rotation.x = -Math.PI / 2;
    ring.position.set(position.x, 0.02, position.z);
    ring.scale.setScalar(0.2);
    this.scene.add(ring);

    const verticalMaterial = material.clone();
    verticalMaterial.color.copy(palette.b);
    verticalMaterial.opacity = 0.55;
    const vertical = new THREE.Mesh(new THREE.TorusGeometry(1, 0.012, 6, 128), verticalMaterial);
    vertical.position.copy(position);
    vertical.position.y = 1.5;
    vertical.scale.setScalar(0.2);
    this.scene.add(vertical);

    this.waves.push({
      ring,
      vertical,
      material,
      verticalMaterial,
      birth: performance.now() / 1000,
      life: 1.35,
      power,
    });
  }

  update(dt) {
    const now = performance.now() / 1000;
    for (let i = this.waves.length - 1; i >= 0; i -= 1) {
      const wave = this.waves[i];
      const progress = (now - wave.birth) / wave.life;
      if (progress >= 1) {
        this.scene.remove(wave.ring, wave.vertical);
        wave.ring.geometry.dispose();
        wave.vertical.geometry.dispose();
        wave.material.dispose();
        wave.verticalMaterial.dispose();
        this.waves.splice(i, 1);
        continue;
      }
      const eased = EASE_OUT(progress);
      const scale = (0.2 + eased * (4.2 + wave.power * 2.4)) * wave.power;
      wave.ring.scale.setScalar(scale);
      wave.material.opacity = 0.85 * (1 - progress);
      wave.vertical.scale.setScalar(0.2 + eased * (2.4 + wave.power * 1.6));
      wave.vertical.rotation.z += dt * 0.6;
      wave.verticalMaterial.opacity = 0.55 * (1 - progress);
    }
  }
}

export class BurstSystem {
  constructor(scene, quality) {
    this.scene = scene;
    this.bursts = [];
    this.maxBursts = 3;
    this.texture = glowTexture();
    this.particleCount = quality.mobile ? 90 : 170;
  }

  fire(origin, palette, power = 1) {
    if (this.bursts.length >= this.maxBursts) {
      const oldest = this.bursts.shift();
      this.scene.remove(oldest.points);
      oldest.geometry.dispose();
      oldest.material.dispose();
    }

    const count = Math.floor(this.particleCount * Math.min(1.4, power));
    const positions = new Float32Array(count * 3);
    const colors = new Float32Array(count * 3);
    const velocities = new Float32Array(count * 3);
    const color = new THREE.Color();

    for (let i = 0; i < count; i += 1) {
      positions[i * 3] = origin.x + (Math.random() - 0.5) * 0.1;
      positions[i * 3 + 1] = origin.y + (Math.random() - 0.5) * 0.1;
      positions[i * 3 + 2] = origin.z + (Math.random() - 0.5) * 0.1;

      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      const speed = (0.6 + Math.random() * 2.6) * power;
      velocities[i * 3] = Math.sin(phi) * Math.cos(theta) * speed;
      velocities[i * 3 + 1] = Math.cos(phi) * speed * 0.85 + 0.4;
      velocities[i * 3 + 2] = Math.sin(phi) * Math.sin(theta) * speed;

      const roll = Math.random();
      color.copy(roll < 0.5 ? palette.a : roll < 0.82 ? palette.b : palette.c);
      if (Math.random() < 0.18) color.setRGB(1, 1, 1);
      colors[i * 3] = color.r;
      colors[i * 3 + 1] = color.g;
      colors[i * 3 + 2] = color.b;
    }

    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute("position", new THREE.BufferAttribute(positions, 3).setUsage(THREE.DynamicDrawUsage));
    geometry.setAttribute("color", new THREE.BufferAttribute(colors, 3));
    const material = new THREE.PointsMaterial({
      size: 0.09,
      map: this.texture,
      vertexColors: true,
      transparent: true,
      opacity: 1,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      sizeAttenuation: true,
    });
    const points = new THREE.Points(geometry, material);
    points.frustumCulled = false;
    this.scene.add(points);
    this.bursts.push({ points, geometry, material, velocities, birth: performance.now() / 1000, life: 1.15 });
  }

  update(dt) {
    const now = performance.now() / 1000;
    for (let b = this.bursts.length - 1; b >= 0; b -= 1) {
      const burst = this.bursts[b];
      const progress = (now - burst.birth) / burst.life;
      if (progress >= 1) {
        this.scene.remove(burst.points);
        burst.geometry.dispose();
        burst.material.dispose();
        this.bursts.splice(b, 1);
        continue;
      }
      const position = burst.geometry.attributes.position.array;
      const drag = Math.pow(0.24, dt);
      for (let i = 0; i < burst.velocities.length; i += 3) {
        burst.velocities[i] *= drag;
        burst.velocities[i + 1] = burst.velocities[i + 1] * drag - 1.1 * dt;
        burst.velocities[i + 2] *= drag;
        position[i] += burst.velocities[i] * dt;
        position[i + 1] += burst.velocities[i + 1] * dt;
        position[i + 2] += burst.velocities[i + 2] * dt;
      }
      burst.geometry.attributes.position.needsUpdate = true;
      burst.material.opacity = Math.pow(1 - progress, 1.5);
      burst.material.size = 0.09 * (1 - progress * 0.6);
    }
  }
}

export class DivineAudio {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.padGain = null;
    this.padFilter = null;
    this.enabled = false;
    this.themeIndex = 0;
    this.noiseBuffer = null;
    this.notes = [0, 0, 0, 0];
  }

  init() {
    if (this.ctx) return true;
    const AudioCtor = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtor) return false;
    try {
      this.ctx = new AudioCtor();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0;
      this.master.connect(this.ctx.destination);

      const delay = this.ctx.createDelay(1.0);
      delay.delayTime.value = 0.36;
      const feedback = this.ctx.createGain();
      feedback.gain.value = 0.28;
      const wet = this.ctx.createGain();
      wet.gain.value = 0.22;
      delay.connect(feedback);
      feedback.connect(delay);
      delay.connect(wet);
      wet.connect(this.master);

      this.padFilter = this.ctx.createBiquadFilter();
      this.padFilter.type = "lowpass";
      this.padFilter.frequency.value = 900;
      this.padFilter.Q.value = 2.4;

      this.padGain = this.ctx.createGain();
      this.padGain.gain.value = 0.05;

      this.padFilter.connect(this.padGain);
      this.padGain.connect(this.master);
      this.padGain.connect(delay);

      const frequencies = [110, 164.81, 220, 329.63];
      frequencies.forEach((frequency, index) => {
        const osc = this.ctx.createOscillator();
        osc.type = index % 2 === 0 ? "triangle" : "sine";
        osc.frequency.value = frequency;
        osc.detune.value = (index - 1.5) * 7;
        const gain = this.ctx.createGain();
        gain.gain.value = index === 3 ? 0.1 : 0.2;
        osc.connect(gain);
        gain.connect(this.padFilter);
        osc.start();
        this.notes[index] = osc;
      });

      const lfo = this.ctx.createOscillator();
      lfo.frequency.value = 0.08;
      const lfoGain = this.ctx.createGain();
      lfoGain.gain.value = 180;
      lfo.connect(lfoGain);
      lfoGain.connect(this.padFilter.frequency);
      lfo.start();

      const length = Math.floor(this.ctx.sampleRate * 1.4);
      this.noiseBuffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
      const data = this.noiseBuffer.getChannelData(0);
      for (let i = 0; i < length; i += 1) data[i] = Math.random() * 2 - 1;
      return true;
    } catch (error) {
      this.ctx = null;
      return false;
    }
  }

  async ensure() {
    if (!this.init()) return false;
    try {
      if (this.ctx.state === "suspended") await this.ctx.resume();
      if (!this.enabled) {
        this.enabled = true;
        this.master.gain.cancelScheduledValues(this.ctx.currentTime);
        this.master.gain.setTargetAtTime(0.32, this.ctx.currentTime, 0.3);
      }
      return true;
    } catch (error) {
      return false;
    }
  }

  async toggle() {
    if (!this.ctx) {
      const ready = await this.ensure();
      if (!ready) return false;
      return true;
    }
    if (this.enabled) {
      this.enabled = false;
      this.master.gain.setTargetAtTime(0, this.ctx.currentTime, 0.08);
      return false;
    }
    return this.ensure();
  }

  note(frequency, at, duration, type = "sine", volume = 0.06) {
    if (!this.ctx || !this.enabled) return;
    const now = this.ctx.currentTime + at;
    const osc = this.ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(frequency, now);
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(volume, now + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    osc.connect(gain);
    gain.connect(this.master);
    osc.start(now);
    osc.stop(now + duration + 0.05);
  }

  noise(at, duration, from, to, volume = 0.1) {
    if (!this.ctx || !this.enabled || !this.noiseBuffer) return;
    const now = this.ctx.currentTime + at;
    const source = this.ctx.createBufferSource();
    source.buffer = this.noiseBuffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = "lowpass";
    filter.frequency.setValueAtTime(from, now);
    filter.frequency.exponentialRampToValueAtTime(to, now + duration);
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(volume, now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    source.connect(filter);
    filter.connect(gain);
    gain.connect(this.master);
    source.start(now);
    source.stop(now + duration + 0.05);
  }

  create() {
    [523.25, 659.25, 783.99, 1046.5, 1318.5].forEach((frequency, index) => {
      this.note(frequency, index * 0.065, 0.6 - index * 0.06, index % 2 === 0 ? "sine" : "triangle", 0.055);
    });
    this.note(261.63, 0, 0.8, "sine", 0.03);
  }

  destroy() {
    this.noise(0, 1.1, 2400, 70, 0.16);
    if (this.ctx && this.enabled) {
      const now = this.ctx.currentTime;
      const osc = this.ctx.createOscillator();
      osc.type = "sine";
      osc.frequency.setValueAtTime(110, now);
      osc.frequency.exponentialRampToValueAtTime(28, now + 0.9);
      const gain = this.ctx.createGain();
      gain.gain.setValueAtTime(0.16, now);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + 1.0);
      osc.connect(gain);
      gain.connect(this.master);
      osc.start(now);
      osc.stop(now + 1.05);
    }
  }

  change() {
    [329.63, 415.3, 493.88, 659.25].forEach((frequency, index) => {
      this.note(frequency, index * 0.04, 0.45, "triangle", 0.045);
    });
    this.noise(0, 0.35, 400, 3200, 0.05);
  }

  everything() {
    [130.81, 196, 261.63, 329.63, 392, 523.25].forEach((frequency, index) => {
      this.note(frequency, index * 0.03, 1.4, index % 2 === 0 ? "triangle" : "sine", 0.05);
    });
    this.noise(0, 0.7, 300, 5000, 0.1);
    this.noise(0.18, 1.4, 5000, 200, 0.06);
  }

  setTheme(index) {
    this.themeIndex = index;
    if (!this.ctx || !this.padFilter) return;
    const frequencies = [900, 1250, 1500, 720];
    this.padFilter.frequency.setTargetAtTime(frequencies[index % frequencies.length], this.ctx.currentTime, 0.5);
  }
}

