115:   note(frequency, at, duration, type = "sine", volume = 0.06) {
116:     if (!this.ctx || !this.enabled) return;
117:     const now = this.ctx.currentTime + at;
118:     const osc = this.ctx.createOscillator();
119:     osc.type = type;
120:     osc.frequency.setValueAtTime(frequency, now);
121:     const gain = this.ctx.createGain();
122:     gain.gain.setValueAtTime(0.0001, now);
123:     gain.gain.exponentialRampToValueAtTime(volume, now + 0.012);
124:     gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
125:     osc.connect(gain);
126:     gain.connect(this.master);
127:     osc.start(now);
128:     osc.stop(now + duration + 0.05);
129:   }
