131:   noise(at, duration, from, to, volume = 0.1) {
132:     if (!this.ctx || !this.enabled || !this.noiseBuffer) return;
133:     const now = this.ctx.currentTime + at;
134:     const source = this.ctx.createBufferSource();
135:     source.buffer = this.noiseBuffer;
136:     const filter = this.ctx.createBiquadFilter();
137:     filter.type = "lowpass";
138:     filter.frequency.setValueAtTime(from, now);
139:     filter.frequency.exponentialRampToValueAtTime(to, now + duration);
140:     const gain = this.ctx.createGain();
141:     gain.gain.setValueAtTime(volume, now);
142:     gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
143:     source.connect(filter);
144:     filter.connect(gain);
145:     gain.connect(this.master);
146:     source.start(now);
147:     source.stop(now + duration + 0.05);
148:   }
